package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.util.math.*;
/** Real client walks through a compartment door, sits, dismounts and walks while moving. */
final class SleeperChecks {
 static boolean ready;static volatile int id;static RailVehicleEntity engine,coach,clientCoach;static int phase,age;static Vec3d initial;static int corrections,teleports,visits;static boolean cancelRestSeen;static net.minecraft.server.network.ServerPlayerEntity.Respawn respawn;
 static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 static void register(){if(!Boolean.getBoolean("halloween.sleeperTest"))return;
  ServerTickEvents.END_SERVER_TICK.register(server->{if(ready)return;var w=server.getOverworld();if(w.getPlayers().isEmpty())return;try{for(var old:RailVehicleEntity.nearby(w,new Box(-100,100,-100,100,250,500)))old.discard();var controls=new ArrayList<Vec3d>(RailPath.straight(new Vec3d(0,160,0),new Vec3d(0,160,1200)));controls.addAll(RailPath.straight(new Vec3d(0,160,1200),new Vec3d(150,160,1200)));controls.addAll(RailPath.straight(new Vec3d(150,160,1200),new Vec3d(150,160,0)));controls.addAll(RailPath.straight(new Vec3d(150,160,0),new Vec3d(0,160,0)));var route=new RailPath(controls);var vehicles=RailwayNetwork.spawnTrain(w,route,0,80,1);engine=vehicles.getFirst();engine.setStops(List.of(280d,700d));engine.dwell=Integer.MAX_VALUE;coach=vehicles.get(2);id=coach.getId();require(coach.isSleeper()&&coach.seats().size()==12,"last coach is the sleeper");var cp=new ChunkPos(coach.getBlockPos());for(int x=-2;x<=2;x++)for(int z=-2;z<=12;z++)w.setChunkForced(cp.x+x,cp.z+z,true);w.setTimeOfDay(12000);var p=w.getPlayers().getFirst();p.stopRiding();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setHealth(20);p.getAbilities().flying=false;p.sendAbilitiesUpdate();var start=coach.getEntityPos().add(1.04,1.5,-5.2);p.networkHandler.requestTeleport(start.x,start.y,start.z,0,0);var out=net.minecraft.storage.NbtWriteView.create(net.minecraft.util.ErrorReporter.EMPTY,w.getRegistryManager());coach.writeData(out);var clone=RailContent.VEHICLE.create(w,net.minecraft.entity.SpawnReason.LOAD);clone.readData(net.minecraft.storage.NbtReadView.create(net.minecraft.util.ErrorReporter.EMPTY,w.getRegistryManager(),out.getNbt()));require(clone.isSleeper()&&clone.compartments()==7,"sleeper variant and compartment doors persist");clone.discard();var dummy=new net.minecraft.server.network.ServerPlayerEntity(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"AwakeRestGuard"),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());var anchor=RailContent.SEAT.create(w,net.minecraft.entity.SpawnReason.EVENT);RailRest.REST.put(p,new RailRest.Trip(p,anchor,engine));require(!RailRest.allReady(List.of(p,dummy)),"awake multiplayer guest prevents time skip");RailRest.REST.put(dummy,new RailRest.Trip(dummy,anchor,engine));require(RailRest.allReady(List.of(p,dummy)),"all resting players allow time skip");RailRest.REST.remove(p);RailRest.REST.remove(dummy);anchor.discard();org.slf4j.LoggerFactory.getLogger("sleeper-test").info("PASS multiplayer rest guard rejects awake guest and accepts all resting players");ready=true;}catch(Throwable e){org.slf4j.LoggerFactory.getLogger("sleeper-test").error("FAIL setup",e);server.stop(false);}});
  ClientTickEvents.END_CLIENT_TICK.register(c->{if(!ready||phase<0||c.player==null||c.world==null)return;c.options.pauseOnLostFocus=false;c.options.hudHidden=true;if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);if(clientCoach==null)clientCoach=c.world.getEntityById(id) instanceof RailVehicleEntity t?t:null;if(clientCoach==null)return;age++;try{require(c.player.isAlive()&&c.player.getHealth()>19,"passenger unharmed");var local=RailPassengerNetwork.toLocal(clientCoach,c.player.getEntityPos());
   if(phase==0&&age>35){require(clientCoach.isSleeper(),"client receives sleeper variant");if(walk(c,local,new Vec3d(1.04,1.5,0)))next();}
   else if(phase==1){aim(c,new Vec3d(.62,2.42,.4));if(age==10)c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);if(age>30){require((clientCoach.compartments()&2)==0,"compartment door closes from corridor");next();}}
   else if(phase==2){if(age<35){aim(c,new Vec3d(.62,2.42,.4));if(age==10)c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);}else{require((clientCoach.compartments()&2)!=0,"door opens");if(walk(c,local,new Vec3d(-.3,1.5,0))){next();}}}
   else if(phase==3){aim(c,new Vec3d(.44,2.42,.4));if(age==10)c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);if(age==25){require((clientCoach.compartments()&2)==0&&!c.player.hasVehicle(),"inside click closes door without sitting");}if(age==30)c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);if(age>=45&&age<60)aim(c,new Vec3d(-.3,1.86,1.17));if(age==55)c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);if(age>80){require(c.player.getVehicle() instanceof RailSeatEntity,"lower berth accepts aimed seating");require(Math.abs(local.y+.75-1.90)<.04,"pelvis on lower berth cushion");org.slf4j.LoggerFactory.getLogger("sleeper-test").info("PASS corridor and inside door clicks never sit player; aimed lower berth seating; taller cabin");c.options.sneakKey.setPressed(true);next();}}
   else if(phase==4){if(age==12)c.options.sneakKey.setPressed(false);if(age>35){require(!c.player.hasVehicle(),"ordinary sneak dismount");if(walk(c,local,new Vec3d(1.04,1.5,0))){c.options.setPerspective(net.minecraft.client.option.Perspective.FIRST_PERSON);corrections=RailPassengerClient.corrections;teleports=RailPassengerClient.teleports;c.getServer().execute(()->engine.dwell=36);next();}}}
   else if(phase==5){if(age==65){initial=local;c.options.forwardKey.setPressed(true);c.player.setYaw(0);}if(age>65&&walk(c,local,new Vec3d(1.04,1.5,5.15))){require(local.z-initial.z>4,"walk through corridor while train accelerates");require(RailPassengerClient.corrections==corrections&&RailPassengerClient.teleports==teleports,"no correction teleports");require(TransportSoundClient.playing.containsKey(clientCoach.getUuid()),"moving carriage sound follows actual vehicle");require(TransportSoundClient.playing.get(clientCoach.getUuid()).getVolume()>.02&&c.getSoundManager().isPlaying(TransportSoundClient.playing.get(clientCoach.getUuid())),"rolling audio is actually playing at audible volume");c.options.forwardKey.setPressed(false);c.player.setYaw(180);c.player.setPitch(0);org.slf4j.LoggerFactory.getLogger("sleeper-test").info("PASS dismount and walking in moving sleeper, no correction teleports, moving sound instance");next();}}else if(phase==6&&age>12){net.minecraft.client.util.ScreenshotRecorder.saveScreenshot(c.runDirectory,"sleeper-corridor.png",c.getFramebuffer(),1,t->{});next();}
   else if(phase==7){if(walk(c,local,new Vec3d(1.04,1.5,3.15)))next();}
   else if(phase==8){if(walk(c,local,new Vec3d(-.3,1.5,3.15))){c.getServer().execute(()->{c.getServer().getOverworld().setTimeOfDay(14000);respawn=c.getServer().getOverworld().getPlayers().getFirst().getRespawn();visits=engine.visits;});next();}}
   else if(phase==9){var target=RailGeometry.rotate(new Vec3d(-.52,4.45,4.32),clientCoach.getYaw()).add(clientCoach.getEntityPos());var diff=target.subtract(c.player.getEyePos());c.player.setYaw((float)Math.toDegrees(Math.atan2(-diff.x,diff.z)));c.player.setPitch((float)-Math.toDegrees(Math.atan2(diff.y,diff.horizontalLength())));c.options.sneakKey.setPressed(true);if(age==15){c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);c.options.sneakKey.setPressed(false);next();}}
   else if(phase==10){if(c.player.getVehicle() instanceof RailSeatEntity seat&&seat.resting()){var render=(net.minecraft.client.render.entity.state.PlayerEntityRenderState)c.getEntityRenderDispatcher().getRenderer(c.player).getAndUpdateRenderState(c.player,1);require(render.pose==net.minecraft.entity.EntityPose.SLEEPING,"actual lying sleeping render pose");if(age==25)net.minecraft.client.util.ScreenshotRecorder.saveScreenshot(c.runDirectory,"sleeper-rest.png",c.getFramebuffer(),1,t->{});}if(age>40&&!c.player.hasVehicle()&&engine.visits==visits+1){var p=c.getServer().getOverworld().getPlayers().getFirst();require(Objects.equals(respawn,p.getRespawn()),"night rest never changes respawn point");long time=Math.floorMod(c.getServer().getOverworld().getTimeOfDay(),24000);require(time>=1000&&time<3000,"wake in morning, actual="+time);require(!c.getServer().getTickManager().isSprinting(),"normal simulation resumes");require(Math.abs(engine.distance-280)<1,"train actually reaches next scheduled station");org.slf4j.LoggerFactory.getLogger("sleeper-test").info("PASS real night rest on upper berth, next-station simulation, dawn, unchanged respawn, normal tick mode restored");next();c.getServer().execute(()->c.getServer().getOverworld().setTimeOfDay(14000));}}
   else if(phase==11){var target=RailGeometry.rotate(new Vec3d(-.52,4.45,4.32),clientCoach.getYaw()).add(clientCoach.getEntityPos());var d=target.subtract(c.player.getEyePos());c.player.setYaw((float)Math.toDegrees(Math.atan2(-d.x,d.z)));c.player.setPitch((float)-Math.toDegrees(Math.atan2(d.y,d.horizontalLength())));c.options.sneakKey.setPressed(true);if(age==15){c.interactionManager.interactEntity(c.player,clientCoach,net.minecraft.util.Hand.MAIN_HAND);c.options.sneakKey.setPressed(false);next();}}
   else if(phase==12){if(c.player.getVehicle() instanceof RailSeatEntity seat&&seat.resting())cancelRestSeen=true;if(age==25){require(cancelRestSeen,"second rest actually began before cancellation");c.options.sneakKey.setPressed(true);}if(age==35)c.options.sneakKey.setPressed(false);if(age>45){require(!c.player.hasVehicle()&&RailRest.REST.isEmpty(),"Shift cancels rest");require(!c.getServer().getTickManager().isSprinting(),"cancel restores normal ticking");require(Objects.equals(respawn,c.getServer().getOverworld().getPlayers().getFirst().getRespawn()),"cancel preserves spawn point");org.slf4j.LoggerFactory.getLogger("sleeper-test").info("PASS ordinary Shift cancels rest without time skip or respawn change");phase=-1;c.scheduleStop();}}
   require(age<400,"phase timeout "+phase+" local="+local);
  }catch(Throwable e){phase=-1;c.options.forwardKey.setPressed(false);c.options.sneakKey.setPressed(false);org.slf4j.LoggerFactory.getLogger("sleeper-test").error("FAIL",e);c.scheduleStop();}});
 }
 static void aim(net.minecraft.client.MinecraftClient c,Vec3d local){var target=RailGeometry.rotate(local,clientCoach.getYaw()).add(clientCoach.getEntityPos());var d=target.subtract(c.player.getEyePos());float yaw=(float)Math.toDegrees(Math.atan2(-d.x,d.z)),pitch=(float)-Math.toDegrees(Math.atan2(d.y,d.horizontalLength()));c.player.setYaw(yaw);c.player.setPitch(pitch);c.getNetworkHandler().sendPacket(new net.minecraft.network.packet.c2s.play.PlayerMoveC2SPacket.LookAndOnGround(yaw,pitch,c.player.isOnGround(),false));}
 static void next(){phase++;age=0;}
 static boolean walk(net.minecraft.client.MinecraftClient c,Vec3d p,Vec3d target){var d=target.subtract(p);boolean close=d.horizontalLength()<.16;c.options.forwardKey.setPressed(!close);c.player.setYaw((float)Math.toDegrees(Math.atan2(-d.x,d.z)));c.player.setPitch(0);return close;}
}
